def insert(D, NP, start, n, name, i):
    D[i] = name
    if n == 1:
        NP[i] = start
        return i
    prev = start
    for k in range(2, n):
        prev = NP[prev]
    NP[i] = NP[prev]
    NP[prev] = i
    return start

def delete(NP, start, n):
    if n == 1:
        return NP[start]
    prev = start
    for k in range(2, n):
        prev = NP[prev]
    NP[prev] = NP[NP[prev]]
    return start
